package main

import "github.com/gin-gonic/gin"

func main() {
	r := gin.Default() // 自带 Logger 和 Recovery
	r.GET("/", func(c *gin.Context) { c.String(200, "ok") })

	// gin.New() 返回一个不带任何中间件的引擎
	clean := gin.New()
	clean.Use(gin.Logger(), gin.Recovery()) // 想恢复默认行为就自己挂
	clean.GET("/", func(c *gin.Context) { c.String(200, "ok") })
}

package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	r := gin.New()
	r.GET("/user/:id", func(c *gin.Context) { c.String(200, "用户 "+c.Param("id")) })

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/user/42", nil))
