package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	r := gin.New()
	r.GET("/search", func(c *gin.Context) {
		// Query 取不到返回空串，DefaultQuery 取不到用默认值
		q := c.Query("q")
		name := c.DefaultQuery("name", "匿名")
		c.String(200, "q=%s name=%s", q, name)
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/search?q=gin", nil))
	fmt.Println(w.Body.String())
}

package main

import (
	"fmt"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type User struct {
	Name string `json:"name"`
	Age  int    `json:"age"`
}

func main() {
	r := gin.New()
	r.POST("/users", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(400, gin.H{"error": err.Error()})
			return
		}
		c.JSON(200, u)
	})

	w := httptest.NewRecorder()
	body := strings.NewReader(`{"name":"张三","age":18}`)
	r.ServeHTTP(w, httptest.NewRequest("POST", "/users", body))
	fmt.Println(w.Body.String())
}

