package main

import (
	"fmt"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type User struct {
	Name string `json:"name"`
	Age  int    `json:"age"`
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.Default()
	r.Use(func(c *gin.Context) {
		fmt.Println("[中间件]", c.Request.URL.Path)
		c.Next()
	})

	api := r.Group("/api")
	api.Use(func(c *gin.Context) {
		c.Header("X-API", "v1")
		c.Next()
	})

	v1 := api.Group("/v1")
	v1.GET("/user/:id", func(c *gin.Context) {
		c.JSON(200, gin.H{
			"id":   c.Param("id"),
			"name": c.DefaultQuery("name", "匿名"),
		})
	})
	v1.POST("/user", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(400, gin.H{"error": err.Error()})
			return
		}
		c.JSON(200, u)
	})

	r.NoRoute(func(c *gin.Context) { c.JSON(404, gin.H{"error": "没有这个路由"}) })

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/api/v1/user/42?name=张三", nil))
	fmt.Println(w.Code, w.Body.String())

	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, httptest.NewRequest("POST", "/api/v1/user", strings.NewReader(`{"name":"李四","age":20}`)))
	fmt.Println(w2.Code, w2.Body.String())
}
